def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    sep_rows = {
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != bg
    }
    sep_cols = {
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg
    }

    def ranges(n, separators):
        result, start = [], 0
        for i in range(n):
            if i in separators:
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < n:
            result.append((start, n))
        return result

    row_ranges = ranges(h, sep_rows)
    col_ranges = ranges(w, sep_cols)

    source = None
    for r0, r1 in row_ranges:
        for c0, c1 in col_ranges:
            cells = [
                (r - r0, c - c0, grid[r][c])
                for r in range(r0, r1)
                for c in range(c0, c1)
                if grid[r][c] != bg
            ]
            if cells:
                source = (r1 - r0, c1 - c0, cells)
                break
        if source:
            break

    if source is None:
        return [row[:] for row in grid]

    sh, sw, pattern = source
    out = [row[:] for row in grid]
